      recordId: recordId,
      callId: callId,
      parentCallId: parentCallId,
      name: name,
      argsRaw: argsRaw,
      result: result,
      resultPreviewMarkdown: resultPreviewMarkdown,
      isError: isError,
      timeSeconds: timeSeconds,
      startedAt: startedAt,
    );
  }
}

