/// A finalized assistant response row (`message` kind).
final class TrajectoryAssistantRecord extends TrajectoryRecord {
  /// Creates a [TrajectoryAssistantRecord].
  const TrajectoryAssistantRecord({
    required super.index,
    required super.recordId,
    required this.messageId,
    required this.turn,
    required this.step,
    this.provider,
    this.model,
    this.usage,
    this.inputTokens,
    this.cacheReadTokens,
    this.cacheWriteTokens,
    this.outputTokens,
    this.reasoningTokens,
    this.stepStartTime,
    this.firstTokenTime,
    this.completedTime,
    this.sourceBlocks = const [],
    this.outputBlocks = const [],
    this.partialBlocks = const [],
    this.schemaDetail,
    this.thinkingDetail,
    this.inputDetail,
    this.outputDetail,
    this.promptDetail,
    this.previousPromptDetail,
    this.timeSeconds,
    this.isError,
