+      );
+      expect(
+        () => parseCliArgs(['trajectory', 'export', '--json']),
+        throwsA(isA<CliArgsException>()),
+      );
+    });
+
+    test('unknown verbs still fail fast', () {
+      expect(
+        () => parseCliArgs(['trajectory', 'exportx']),
+        throwsA(isA<CliArgsException>()),
